    this.anomaly = `다음 점프력 ${Math.round(power / t.jump * 100)}% · 껍질 파손 ${s.jumps}회 · 사망 ${s.deaths}회`;
    this.risk = (t.jump - power) / (t.jump - t.minJump) * 100;
