  e1: E1_GRAVITY_DASH, e2: E2_BOUNCE_BALL, e3: E3_HUMAN_STACK,
  e4: E4_ACCELERATION_DASH, e5: E5_SLINGSHOT, e6: E6_GRAVITY_FLIGHT,
  e7: E7_ROULETTE, e8: E8_SEESAW, e9: E9_ICE_CURLING,
